// EDIT THIS MAP: left side is the GRC field, right side is the field name in your claims system.
const MAP = {
  external_id: 'claimId', claim_number: 'claimId', policy_number: 'policyNo', claim_type: 'type',            // Cashless or Reimbursement
  status: 'status', claim_amount: 'amount', approved_amount: 'approvedAmount', registration_date: 'registeredAt',
  preauth_request_at: 'preAuthRequestedAt', preauth_response_at: 'preAuthDecidedAt',
  discharge_request_at: 'dischargeRequestedAt', discharge_response_at: 'dischargeDecidedAt',
  documents_complete_at: 'lastDocumentAt', decision_date: 'decidedAt', settlement_date: 'settledAt',
  rejection_reason: 'rejectionReason', approver_level: 'approverLevel', manual_override: 'override', override_reason: 'overrideReason',
  extension_documented: 'extensionDocumented', extension_reason: 'extensionReason',
};
// Deliberately NOT mapped: patient names, diagnoses and other health details. The timeline rules do not need them.
const rows = $input.all().flatMap(i => Array.isArray(i.json) ? i.json : (i.json.claims || i.json.data || [i.json])).filter(r => r && Object.keys(r).length);
if (!rows.length) return [];
const records = rows.map(r => Object.fromEntries(Object.entries(MAP).map(([k, v]) => [k, r[v]]).filter(([, v]) => v !== undefined && v !== null && v !== '')));
return [{ json: { records } }];
